INSERT INTO knowledge (id, system, title, content, tags, source_url, published) VALUES
('csolution', 'general', 'Connect Solution', 'Connect Solution (CSolution) inatoa mifumo ya Wi-Fi billing ya WoteFy na LubFy. Tofauti kuu ni vifaa vinavyotumika. Uliza brand, model na mazingira ya mteja kabla ya kupendekeza setup mahususi.', 'csbot wifi wi-fi billing hotspot biashara huduma msaada installation configuration support', NULL, true),
('sinza', 'general', 'Ofisi ya CSolution', 'Ofisi ipo Sinza Makaburini, Dar es Salaam, karibu na Lantana Hotel, kwenye fremu zenye milango ya kijani.', 'ofisi location mahali eneo directions address wapi sinza maelekezo ramani', NULL, true),
('wotefy', 'wotefy', 'WoteFy kwa TP-Link Omada', 'WoteFy ina captive portal yenye chapa ya biashara, malipo ya mobile money, na usimamizi wa Omada. Wi-Fi billing inatumia Omada EAP. Gateways, switches na controllers za Omada zinaweza kuwa sehemu ya mtandao. Programu ya Android inapatikana kupitia kiungo cha Download app kwenye tovuti ya WoteFy.', 'wotefy ssdomada tp-link tplink omada eap gateway switch android app features wifi hotspot', 'https://ssdomada.site/', true),
('lubfy', 'lubfy', 'LubFy kwa vifaa vya vendors tofauti', 'LubFy inasimamia biashara ya hotspot kwenye sites nyingi, vouchers, captive portal, malipo na sessions. Vendors walioorodheshwa ni MikroTik, Cudy, TP-Link Omada, Ruijie/Reyee, Cambium na Ubiquiti UniFi. Mahitaji ya setup na uwezo wa kufanya kazi bila router ya ziada hutegemea model, firmware na integration.', 'lubfy cudy mikrotik unifi cambium reyee ruijie tplink omada hotspot setup features', 'https://lubfy.online/', true);
